# Extract each "band" as a tuple of rows
def get_band_shape(input_grid, bg_color):
    bands = []
    current = None
    start_row = None

    for i, row in enumerate(input_grid):
        non_bg = [x for x in row if x != bg_color and x != 0]

        if non_bg and not current:
            # Starting a new band
            current = {'color': non_bg[0], 'rows': [], 'start': i}
        elif non_bg and current:
            # Continue current band
            current['rows'].append(row.copy())
        else:
            # Band ended
            if current:
                bands.append((current['color'], current))
                current = None

    return bands

